        // cache interceptor has to understand it when it runs after dns
        for (const [path, dispatcher] of [
          ['/', new Agent().compose(interceptors.dns(), interceptors.cache())],
          ['/', new Agent().compose(interceptors.cache(), interceptors.dns())],
          ['/redirect', new Agent().compose(interceptors.dns(), interceptors.cache(), interceptors.redirect({ maxRedirections: 3 }))],
