cat > /tmp/repro.mjs <<'EOF'
import { createServer } from 'node:http'
import { Agent, interceptors, request } from './index.js'

const { cache, dns, redirect } = interceptors

const server = createServer((req, res) => {
  if (req.url === '/redirect') {
    res.writeHead(302, { location: '/' })
    res.end()
    return
  }
  res.writeHead(200, { 'content-type': 'text/plain' })
  res.end('ok')
}).listen(0)
await new Promise(r => server.once('listening', r))
const url = `http://localhost:${server.address().port}`

for (const [name, dispatcher] of [
  ['dnsThenCache', new Agent().compose(dns(), cache())],
  ['cacheThenDns', new Agent().compose(cache(), dns())]
]) {
  for (const headers of [[], {}, undefined, ['x-a', '1'], [['x-a', '1']], new Headers({ 'x-a': '1' })]) {
    const r = await request(url, { dispatcher, headers })
    console.log(name, JSON.stringify(headers ?? null), r.statusCode)
    r.body.destroy()
  }
}

for (const [name, dispatcher] of [
  ['dnsThenCache+redirect', new Agent().compose(dns(), cache(), redirect({ maxRedirections: 3 }))],
  ['cacheThenDns+redirect', new Agent().compose(cache(), dns(), redirect({ maxRedirections: 3 }))]
]) {
  const r = await request(`${url}/redirect`, { dispatcher })
  console.log(name, r.statusCode)
  r.body.destroy()
}

server.close()
EOF
